const QUESTIONS = RAW_QUESTIONS.map(([subject, difficulty, q, correct, wrong, explain], i) => ({
  id: i, subject, difficulty, q, correct, wrong, explain,
}));

/** Fisher–Yates shuffle (returns a new array). */
function shuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

/** Returns the four answer choices in random order plus the index of the correct one. */
function shuffledChoices(question) {
  const choices = shuffle([question.correct, ...question.wrong]);
  return { choices, answerIndex: choices.indexOf(question.correct) };
}

/** Safe localStorage helpers (private browsing can throw). */
const store = {
  get(key, fallback) {
    try { const v = localStorage.getItem(key); return v === null ? fallback : JSON.parse(v); }
    catch { return fallback; }
  },
  set(key, value) {
    try { localStorage.setItem(key, JSON.stringify(value)); } catch { /* ignore */ }
  },
};
